add_action( 'woocommerce_before_calculate_totals', 'perfectpixel_bogo_gift', 5 );

function perfectpixel_bogo_gift( $cart ) {
	static $running = false;
	$trigger = (int) '{{bogo_trigger_id}}';
	$gift    = (int) '{{bogo_gift_id}}';
	if ( $running || ! $trigger || ! $gift || ( is_admin() && ! wp_doing_ajax() ) ) {
		return;
	}
	$has_trigger = false;
	$gift_key    = '';
	foreach ( $cart->get_cart() as $key => $item ) {
		if ( (int) $item['product_id'] === $trigger ) {
			$has_trigger = true;
		}
		if ( ! empty( $item['perfectpixel_bogo'] ) ) {
			$gift_key = $key;
		}
	}

	$running = true;
	if ( $has_trigger && ! $gift_key ) {
		$cart->add_to_cart( $gift, 1, 0, array(), array( 'perfectpixel_bogo' => 1 ) );
	} elseif ( ! $has_trigger && $gift_key ) {
		$cart->remove_cart_item( $gift_key );
	}
	$running = false;

	foreach ( $cart->get_cart() as $key => $item ) {
		if ( ! empty( $item['perfectpixel_bogo'] ) ) {
			$item['data']->set_price( 0 );
			$cart->cart_contents[ $key ]['quantity'] = 1;
		}
	}
}
